            q(185, "State Space Analysis", "The state matrix A of a system has dimensions n x n. What is the dimension of the state transition matrix Φ(t)?", listOf("n x n", "n x 1", "1 x n", "n x m"), "n x n"),
            q(186, "Mathematical Modeling & Transfer Function", "A system is described as time-invariant if its parameters:", listOf("Do not change with time.", "Change linearly with time.", "Are independent of the input signal amplitude.", "Are strictly zero at the start."), "Do not change with time."),
            q(187, "Block Diagram Reduction", "When reducing block diagrams, cascading two blocks is mathematically equivalent to which operation?", listOf("Multiplication of their transfer functions", "Addition of their transfer functions", "Subtraction of their transfer functions", "Division of their transfer functions"), "Multiplication of their transfer functions"),
            q(188, "Signal Flow Graphs", "Can a forward path pass through a node more than once?", listOf("No, by definition a forward path must visit each node at most once.", "Yes, if it contains a feedback loop.", "Yes, forward paths can cross nodes infinitely.", "No, forward paths cannot contain nodes."), "No, by definition a forward path must visit each node at most once."),
            q(189, "Time Response Analysis", "What is the value of the damping ratio for an undamped system?", listOf("0", "1", "0.707", "Greater than 1"), "0"),
            q(190, "Steady State Error", "What is the velocity error constant Kv for a Type-0 system?", listOf("0", "Infinity", "A finite constant value", "1"), "0"),
            q(191, "Stability & Routh-Hurwitz", "If a system has roots exactly on the jω-axis that are non-repeated, the system is structurally:", listOf("Marginally stable", "Stable", "Unstable", "Completely unstable"), "Marginally stable"),
            q(192, "Root Locus", "The value of system gain K is always what value at any open loop pole location on the root locus plot?", listOf("0", "Infinity", "1", "-1"), "0"),
            q(193, "Frequency Response Analysis", "The phase margin of an unstable closed-loop system is typically:", listOf("Negative", "Positive", "Zero", "Greater than 90°"), "Negative"),
            q(194, "Bode Plots", "A factor of (1 + sT) in the denominator contributes what phase shift when ω matches the corner frequency 1/T?", listOf("-45°", "+45°", "-90°", "0°"), "-45°"),
            q(195, "Polar & Nyquist Plots", "The intersection point of a Nyquist plot with the negative real axis is used directly to determine which metric?", listOf("Gain Margin", "Phase Margin", "Steady State Error", "Bandwidth"), "Gain Margin"),
            q(196, "Compensators & Controllers", "A lead compensator has what primary impact on system bandwidth?", listOf("It increases the bandwidth, resulting in a faster system response speed.", "It decreases the bandwidth, filtering high frequency noise.", "It has zero impact on bandwidth parameters.", "It reduces the bandwidth to zero value."), "It increases the bandwidth, resulting in a faster system response speed."),
            q(197, "State Space Analysis", "The identity matrix I satisfies which characteristic relation for any state matrix A?", listOf("A * I = I * A = A", "A * I = 0", "I * I = 0", "A + I = A"), "A * I = I * A = A"),
            q(198, "Mathematical Modeling & Transfer Function", "What is the relation between the unit impulse response and the unit step response of an LTI system?", listOf("The impulse response is the derivative of the step response.", "The impulse response is the integral of the step response.", "The step response is the derivative of the impulse response.", "They are identical."), "The impulse response is the derivative of the step response."),
            q(199, "Steady State Error", "What is the steady state error of a Type-2 system when subjected to a unit ramp input?", listOf("0", "1 / Kv", "Infinity", "A finite constant value"), "0"),
            q(200, "Stability & Routh-Hurwitz", "If a system has a characteristic equation s^5 + s^4 + 2s^3 + 2s^2 + 3s + 3 = 0, the row of zeros will appear at which row power in the Routh table?", listOf("s^3 row", "s^4 row", "s^2 row", "s^1 row"), "s^3 row")
        )
    }

    private fun q(
        id: Int,
        subdomain: String,
        question: String,
        options: List<String>,
        answer: String
    ): GateQuestion {
        val topicId = when (subdomain) {
            "Aptitude" -> "cs_general_aptitude"
            "Logical Reasoning" -> "cs_general_aptitude"
            "Verbal Ability" -> "cs_general_aptitude"
            "Mathematical Modeling & Transfer Function",
            "Block Diagram Reduction",
            "Signal Flow Graphs" -> "cs_math_modeling"
            "Time Response Analysis",
            "Steady State Error" -> "cs_time_response"
            "Stability & Routh-Hurwitz",
            "Root Locus" -> "cs_stability"
            "Frequency Response Analysis",
            "Bode Plots",
            "Polar & Nyquist Plots" -> "cs_freq_response"
            "Compensators & Controllers" -> "cs_controllers_comp"
            "State Space Analysis" -> "cs_state_space"
            else -> "cs_math_modeling"
        }

        val subtopicId = when (subdomain) {
            "Aptitude" -> "cs_apt_quantitative"
            "Logical Reasoning" -> "cs_apt_logical"
            "Verbal Ability" -> {
                when {
                    question.contains("_______") -> "cs_apt_verbal_completion"
                    question.contains("synonym", ignoreCase = true) || question.contains("antonym", ignoreCase = true) || question.contains("definition for", ignoreCase = true) || question.contains("idiom", ignoreCase = true) -> "cs_apt_verbal_vocab"
                    question.contains("grammatically", ignoreCase = true) || question.contains("sentence from", ignoreCase = true) -> "cs_apt_verbal_grammar"
                    question.contains("passage", ignoreCase = true) || question.contains("read the", ignoreCase = true) -> "cs_apt_verbal_reading"
                    else -> "cs_apt_verbal_vocab"
                }
            }
            "Mathematical Modeling & Transfer Function" -> "cs_mm_tf_model"
            "Block Diagram Reduction" -> "cs_mm_block"
            "Signal Flow Graphs" -> "cs_mm_sfg"
            "Time Response Analysis" -> "cs_tr_analysis"
            "Steady State Error" -> "cs_tr_steady_error"
            "Stability & Routh-Hurwitz" -> "cs_stab_routh"
            "Root Locus" -> "cs_stab_locus"
            "Frequency Response Analysis" -> "cs_fr_analysis"
            "Bode Plots" -> "cs_fr_bode"
            "Polar & Nyquist Plots" -> "cs_fr_nyquist"
            "Compensators & Controllers" -> "cs_ctrl_compensators"
            "State Space Analysis" -> "cs_ss_analysis"
            else -> "cs_mm_tf_model"
        }

        val correctIdx = options.indexOf(answer).let { if (it == -1) 0 else it }

        val difficulty = when (id % 3) {
            0 -> "Easy"
            1 -> "Medium"
            else -> "Hard"
        }

        val formulas = when (subtopicId) {
            "cs_apt_quantitative" -> "Numerical formulas & standard calculations"
            "cs_apt_logical" -> "Logical sequencing and pattern extraction rules"
            "cs_apt_verbal_grammar", "cs_apt_verbal_completion", "cs_apt_verbal_vocab", "cs_apt_verbal_reading", "cs_apt_verbal" -> "English concord, sentence logic and semantic rules"
            "cs_mm_tf_model" -> "Y(s)/X(s) Laplace transfer function formulation"
            "cs_mm_block" -> "Block diagram reduction algebra"
            "cs_mm_sfg" -> "Mason's Gain Formula: T = (1/Δ) * ∑ (P_k * Δ_k)"
            "cs_tr_analysis" -> "Second-order transient equations"
            "cs_tr_steady_error" -> "e_ss = lim_{s->0} s*R(s)/(1+G(s)H(s))"
            "cs_stab_routh" -> "Routh-Hurwitz array sign changes"
            "cs_stab_locus" -> "Centroid, breakaway criteria dG(s)H(s)/ds = 0"
            "cs_fr_analysis" -> "Frequency domain parameters"
            "cs_fr_bode" -> "Bode asymptote slope rules"
            "cs_fr_nyquist" -> "Nyquist Encirclement Theorem N = Z - P"
            "cs_ctrl_compensators" -> "Phase angle max shift and controller characteristics"
            "cs_ss_analysis" -> "dx/dt = Ax + Bu, STM φ(t) = L^-1{(sI - A)^-1}"
            else -> "LTI feedback identification"
        }

        val explanationText = "Based on fundamental $subdomain concepts. The correct choice is: '$answer'. " +
            when (subtopicId) {
                "cs_apt_quantitative" -> "Based on quantitative problem solving logic. The correct choice is: '$answer'."
                "cs_apt_logical" -> "Based on deductive patterns and logical constraints. The correct choice is: '$answer'."
                "cs_apt_verbal_grammar", "cs_apt_verbal_completion", "cs_apt_verbal_vocab", "cs_apt_verbal_reading", "cs_apt_verbal" -> "Based on reading, usage and grammar principles. The correct choice is: '$answer'."
                "cs_mm_tf_model" -> "For zero initial conditions, taking the Laplace transform of the differential equation yields the transfer function G(s) = Y(s)/X(s)."
                "cs_mm_block" -> "Applying standard block diagram simplification rules (adding forward blocks and resolving negative/positive feedback loops)."
                "cs_mm_sfg" -> "Mason's Gain Formula simplifies the Signal Flow Graph structure by using loops and forward path cofactors."
                "cs_tr_analysis" -> "The time domain transient response depends on the damping ratio (ζ) and natural frequency (ω_n) of the system."
                "cs_tr_steady_error" -> "Steady-state error evaluates tracking performance, defined as the limit of the error signal as time approaches infinity."
                "cs_stab_routh" -> "Routh-Hurwitz criteria determines absolute stability using row sign changes to locate right-half plane poles."
                "cs_stab_locus" -> "Root locus plots roots of the characteristic equation on the s-plane as feedback gain varies from 0 to infinity."
                "cs_fr_analysis" -> "Frequency response provides amplitude ratio and phase differences over a range of sinusoidal input frequencies."
                "cs_fr_bode" -> "Bode plots display frequency domain characteristics using logarithmic coordinates, simplifying cascade system analysis."
                "cs_fr_nyquist" -> "Nyquist criterion checks closed-loop stability from the open-loop frequency response curve's encirclements of the critical point (-1, j0)."
                "cs_ctrl_compensators" -> "Lead/lag compensators and PID controllers modulate poles and zeros to achieve transient and steady-state specifications."
                "cs_ss_analysis" -> "State-space modeling provides an internal, multi-input multi-output state variables formulation in the time domain."
                else -> "Verify the standard feedback principles."
            }

        return GateQuestion(
            id = "cs_q_$id",
            subjectId = "control_systems",
            topicId = topicId,
            subtopicId = subtopicId,
            year = 2020 + (id % 7),
            questionText = question,
            questionType = QuestionType.MCQ,
            options = options,
            correctOptions = listOf(correctIdx),
            correctNumericalRange = null,
            explanation = explanationText,
            formulasUsed = formulas,
            shortcutTricks = "Analyze dimensions, signs, and asymptotic limits of standard formulas.",
            relatedConcepts = "Control engineering, feedback modeling, $subdomain",
            difficulty = difficulty
        )
    }
}
